recipes.command:
mkdir -p bots/telegram_bot && cd bots/telegram_bot && npm init -y && npm install telegraf dotenv && cat << 'TEOF' > index.js
import { Telegraf } from 'telegraf';
const bot = new Telegraf(process.env.BOT_TOKEN || 'SEU_TOKEN_AQUI');
bot.start((ctx) => ctx.reply('VERY SYSTEMS Telegram Bot Ativo!'));
bot.launch();
console.log('Bot de Telegram inicializado!');
TEOF
echo 'Script do Telegram criado em bots/telegram_bot/index.js'
